static bool bond_should_use_rtnl(struct bonding *bond)
{
	struct slave *slave;
	struct list_head *iter;

	if (bond->params.use_carrier)
		return false;

	bond_for_each_slave_rcu(bond, slave, iter) {
		if (!netif_running(slave->dev))
			continue;
		if (slave->dev->ethtool_ops->get_link &&
		    !netdev_need_ops_lock(slave->dev))
			return true;
	}

	return false;
}

